<h1>Product Catalog</h1>

<div class="catalog-layout">
    <!-- Sidebar Filters -->
    <aside class="catalog-sidebar">
        <h4>Filters</h4>

        @if (categories is not null)
        {
            <div class="filter-section">
                <h5>Category</h5>
                @foreach (var category in categories)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
                               checked="@selectedCategories.Contains(category)"
                               @onchange="@(e => ToggleCategory(category, (bool)e.Value!))" />
                        <label class="form-check-label" for="@($"cat-{category}")">@category</label>
                    </div>
                }
            </div>
        }

        <div class="filter-section">
            <h5>Price Range</h5>
            <div class="mb-2">
                <label class="form-label">Min Price</label>
                <input type="number" class="form-control form-control-sm" min="0" step="0.01"
                       @bind="minPrice" />
            </div>
            <div class="mb-2">
                <label class="form-label">Max Price</label>
                <input type="number" class="form-control form-control-sm" min="0" step="0.01"
                       @bind="maxPrice" />
            </div>
        </div>

        <div class="filter-section">
            <div class="form-check">
                <input class="form-check-input" type="checkbox" id="inStockOnly"
                       @bind="inStockOnly" />
                <label class="form-check-label" for="inStockOnly">In Stock Only</label>
            </div>
        </div>

        <div class="filter-actions">
            <button class="btn btn-primary w-100 mb-2" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    <!-- Main Content -->
    <section class="catalog-main">
        @if (errorMessage is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error:</strong> @errorMessage
            </div>
        }
        else if (isLoading)
        {
            <div class="d-flex justify-content-center align-items-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
                <span class="ms-3">Loading products...</span>
            </div>
        }
        else if (searchResult is not null)
        {
            <!-- Toolbar -->
            <div class="catalog-toolbar">
                <div class="d-flex align-items-center gap-3">
                    <label class="form-label mb-0 text-nowrap">Sort by:</label>
                    <select class="form-select form-select-sm" style="width: auto;"
                            value="@sortBy" @onchange="OnSortChanged">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A-Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                <span class="text-muted">
                    Showing @ShowingStart–@ShowingEnd of @searchResult.TotalCount products
                </span>
            </div>

            @if (searchResult.Items.Count == 0)
            {
                <div class="alert alert-info text-center my-4" role="alert">
                    No products found matching your filters. Try adjusting your criteria.
                </div>
            }
            else
            {
                <!-- Product Grid -->
                <div class="product-grid">
                    @foreach (var product in searchResult.Items)
                    {
                        <ProductCard Product="product"
                                     OnProductSelected="HandleProductSelected"
                                     OnAddToCart="HandleAddToCart" />
                    }
                </div>

                <!-- Pagination -->
                @if (TotalPages > 1)
                {
                    <nav aria-label="Product pagination" class="mt-4">
                        <ul class="pagination justify-content-center">
                            <li class="page-item @(currentPage == 1 ? "disabled" : "")">
                                <button class="page-link" @onclick="@(() => GoToPage(currentPage - 1))"
                                        disabled="@(currentPage == 1)">
                                    Previous
                                </button>
                            </li>
                            @foreach (var page in PageNumbers)
                            {
                                <li class="page-item @(page == currentPage ? "active" : "")">
                                    <button class="page-link" @onclick="@(() => GoToPage(page))">@page</button>
                                </li>
                            }
                            <li class="page-item @(currentPage == TotalPages ? "disabled" : "")">
                                <button class="page-link" @onclick="@(() => GoToPage(currentPage + 1))"
                                        disabled="@(currentPage == TotalPages)">
                                    Next
                                </button>
                            </li>
                        </ul>
                    </nav>
                }
            }
        }
    </section>
</div>

