@using sv_a98e45cb392c413091388583d2c5b781.Services

<div class="product-card" @onclick="OnCardClicked" role="button" tabindex="0">
    <div class="product-image" title="@Product.Name">
        @Product.Name
    </div>
    <div class="product-info">
        <h6 class="product-name" title="@Product.Name">@Product.Name</h6>
        <div class="product-price">@Product.Price.ToString("C")</div>
        <div class="product-rating" title="@($"{Product.Rating:F1} out of 5")">
            @GetStarRating(Product.Rating)
        </div>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger">Out of Stock</span>
        }
        <button class="btn btn-sm btn-success mt-2 w-100"
                disabled="@(!Product.InStock)"
                @onclick="OnAddToCartClicked"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task OnCardClicked()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private async Task OnAddToCartClicked()
    {
        if (Product.InStock)
        {
            await OnAddToCart.InvokeAsync(Product);
        }
    }

    private static string GetStarRating(double rating)
    {
        int fullStars = (int)Math.Round(rating);
        int emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

